for L in range(24):
    dp = load(f'model.language_model.layers.{L}.mlp.down_proj.weight').float()  # [1024, 3584]
    act = np.load(d+f'/mlp_act_L{L}.npy').astype(np.float32)  # [4, 1386, 3584]
    ct = dp.T @ r_think.numpy() if hasattr(r_think,'numpy') else None
    cwt = dp.T @ r_wait.numpy()
    gap = ct - cwt  # [3584]
    for name,(ti,p) in positions.items():
        attrib[(L,name)] = act[ti,p]*gap / math.sqrt((h24[ti,p]**2).mean()+1e-6)
    del dp, act
print('done')

